{
  "action": "final",
  "output": {
    "research_concepts": [
      "lineup coverage (≥1 organizer, shaper, terminal)",
      "structural roles: organizer, shaper, terminal",
      "within-team variation in coverage",
      "separability from talent/player counts",
      "talent control behaviour"
    ],
    "methodological_questions": [
      "How to define and measure lineup coverage?",
      "How to separate coverage from talent and player counts?",
      "Does coverage vary within team?",
      "Is the coverage effect separable from talent?",
      "How to control for talent in lineup studies?"
    ],
    "historical_evidence": [],
    "failed_approaches": [],
    "evidence_establishes": [
      "No prior work has directly tested lineup coverage of structural roles (organizer, shaper, terminal)."
    ],
    "evidence_does_not_establish": [
      "Whether coverage varies within team in the available data.",
      "Whether any coverage effect is separable from talent and player counts.",
      "How talent control will behave in such a model."
    ],
    "own_inferences": [
      "Role labels (organizer, shaper, terminal) can be assigned from play-by-play initiator data using the Structural Influence paper definitions (usage and residual influence).",
      "420,993 possessions and 90 team-seasons provide a large number of stints, making within-team variation detectable for most teams.",
      "Some teams may lack one role entirely (e.g., no true shaper), which would restrict coverage variation; this is a form of exposure sparsity.",
      "A talent metric (e.g., offensive RAPM, prior-season PPP) can be computed per player and aggregated to the lineup level as a control.",
      "The question is fundamentally observational; causal interpretation requires strong ignorability given controls, which is plausible but uncertain."
    ],
    "uncertainties": [
      "Reliability of role classification for borderline-usage players or small-sample players, which may misclassify some lineups.",
      "The exact talent metric to control for is not specified; different metrics could yield different estimates.",
      "Some team-seasons may have zero lineups without coverage, reducing effective sample for within-team analysis.",
      "Season-long role assignment may inadvertently use information from the same games if not held out temporally (look-ahead leakage)."
    ],
    "historical_effect": {
      "changed_decision": "no_historical_evidence",
      "explanation": "No prior study family addressed lineup coverage of structural roles; the decision is based solely on data availability, feasibility reasoning, and risk assessment."
    },
    "testability": {
      "p_testable": 0.75,
      "blocking_constraints": [
        {
          "code": "EXPOSURE_SPARSITY",
          "text": "Some teams may have few or zero stints without coverage (missing an organizer, shaper, or terminal), removing within-team variation for those teams."
        },
        {
          "code": "MEASURE_RELIABILITY",
          "text": "Role labels rely on residual influence and usage thresholds; classification noise may dilute effect estimates."
        }
      ]
    },
    "prior_work": {
      "already_answered": "no",
      "cited": [],
      "summary": "No earlier work has investigated lineup coverage of structural roles. Related work on structural concentration and defensive vulnerability (FAM:SF-PAP-024) was rejected, but does not address coverage directly."
    },
    "risks": [
      {
        "code": "EXPOSURE_SPARSITY",
        "text": "Teams that always have all three roles on the floor (or never do) provide no within-team variation, reducing effective sample size."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "Role misclassification due to low-usage players or noisy residual influence may cause measurement error in the coverage indicator."
      },
      {
        "code": "CONFOUNDING",
        "text": "Talent is a primary confound; omitted variables (e.g., opponent quality, game context) could bias the coverage coefficient."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "Using season-long role labels to classify lineups from the same season may inadvertently exploit future information; temporal hold-out is needed."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Within-team subgroup analyses (e.g., per team) may have low power; aggregating across teams mitigates but requires appropriate standard errors."
      }
    ],
    "predicted_outcome": {
      "supported": 0.45,
      "rejected": 0.15,
      "untestable": 0.10,
      "artifact": 0.05,
      "uncertain": 0.25
    },
    "decision": "proceed_with_changes",
    "design": {
      "estimand": "Average effect of lineup coverage (binary: lineup contains ≥1 organizer, ≥1 shaper, ≥1 terminal) on offensive points per possession, after controlling for talent and possession count.",
      "unit": "Lineup stint (fixed five-player offensive unit while on floor), aggregated to stint-level PPP and covariate averages.",
      "sample": "NBA 2023-24, 2024-25, and 2025-26 regular season stints (excluding garbage time, final 2 minutes with score diff ≥20). Minimum 5 possessions per stint. Role labels computed from prior-season data where player had ≥200 initiations; rookies/low-usage players assigned 'Role Occupant' to avoid look-ahead.",
      "power": "Approximately 90 team-seasons; expecting >1,000 stints with both covered and uncovered lineups. Power analysis via simulation using historical within-team coverage rate and assumed effect size d=0.05–0.10 PPP. Exact power to be computed at pre-registration; minimum detectable effect ≤0.03 PPP targeted.",
      "controls": [
        "Sum of offensive player talent (e.g., 3-year RAPM or offensive EPM) for the five offensive players.",
        "Home/away indicator.",
        "Opponent defensive rating (season-to-date).",
        "Game quarter (1/2/3/4) and score margin binned.",
        "Team and season fixed effects."
      ],
      "falsification": [
        "Placebo test: randomly permute coverage labels within team-season, re-estimate effect; true effect should be near zero and confidence interval should include zero.",
        "Negative control: use 'coverage' defined with a structurally irrelevant role grouping (e.g., ≥1 organizer, ≥1 role occupant, ≥1 terminal, omitting shaper) and confirm a null or much smaller effect.",
        "Talent confound test: regress coverage on talent sum; if R² > 0.5, talent control may be insufficient—report and adjust."
      ],
      "multiplicity": "Primary hypothesis is one-tailed test of positive coverage effect. Secondary test of within-team variation uses descriptive statistics and binomial test per team (Bonferroni-corrected across 90 team-seasons). All supplementary analyses reported as exploratory.",
      "decision_rule": "One-tailed p < 0.01 for coverage coefficient in the full model (after confirming falsification tests pass). Within-team variation deemed present if ≥70% of teams have at least one covered and one uncovered stint (descriptive).",
      "data_version": "NBA stats API 2023-24 to 2025-26 regular season, freeze as of 2026-07-13. Derived play-type possession records from graph database."
    }
  }
}

